document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button)});document.querySelectorAll('.project').forEach(p=>p.hidden=button.dataset.filter!=='All'&&p.dataset.category!==button.dataset.filter)}));document.querySelectorAll('[data-filter]').forEach((b,i)=>b.setAttribute('aria-pressed',i===0));const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',open)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section-head,.services article,.about-intro,.principles article,.steps article,.quality-grid article,.faq>div,.contact-bottom').forEach(el=>{el.classList.add('reveal');observer.observe(el)});const sectionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){document.querySelectorAll('nav a').forEach(link=>link.setAttribute('aria-current',link.hash==='#'+entry.target.id?'true':'false'))}}),{rootMargin:'-15% 0px -60% 0px'});document.querySelectorAll('main section[id]').forEach(section=>sectionObserver.observe(section))}
// A section-aware compass: native disclosure, anchor links, and adjacent-section shortcuts.
const compass=document.querySelector('.portfolio-compass');
const compassMenu=compass.querySelector('details');
const compassLinks=[...compass.querySelectorAll('a')];
const compassSections=compassLinks.map(link=>document.querySelector(link.hash));
let compassIndex=0,compassFrame=0;
function updateCompass(){compassFrame=0;let current=0;const marker=Math.min(innerHeight*.3,200);compassSections.forEach((section,index)=>{if(section.getBoundingClientRect().top<=marker)current=index});if(innerHeight+scrollY>=document.documentElement.scrollHeight-4)current=compassSections.length-1;compassIndex=current;document.querySelector('#compass-current').textContent=compassLinks[current].childNodes[1].textContent.trim();compassLinks.forEach((link,index)=>{if(index===current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});compass.querySelector('[data-direction="-1"]').disabled=current===0;compass.querySelector('[data-direction="1"]').disabled=current===compassSections.length-1;const range=document.documentElement.scrollHeight-innerHeight;compass.querySelector('.compass-progress span').style.width=`${range>0?Math.min(100,Math.max(0,scrollY/range*100)):100}%`}
function goToSection(index){const section=compassSections[index];if(!section)return;compassMenu.open=false;section.setAttribute('tabindex','-1');section.focus({preventScroll:true});section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});history.replaceState(null,'',`#${section.id}`)}
compassLinks.forEach((link,index)=>link.addEventListener('click',event=>{event.preventDefault();goToSection(index)}));compass.querySelectorAll('[data-direction]').forEach(button=>button.addEventListener('click',()=>goToSection(compassIndex+Number(button.dataset.direction))));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&compassMenu.open){compassMenu.open=false;compassMenu.querySelector('summary').focus()}});document.addEventListener('pointerdown',event=>{if(!compass.contains(event.target))compassMenu.open=false});function scheduleCompass(){if(!compassFrame)compassFrame=requestAnimationFrame(updateCompass)}addEventListener('scroll',scheduleCompass,{passive:true});addEventListener('resize',scheduleCompass);addEventListener('load',scheduleCompass);if('ResizeObserver' in window)new ResizeObserver(scheduleCompass).observe(document.body);updateCompass();

const themeButton=document.querySelector('.theme-toggle');
function applyTheme(theme){document.documentElement.dataset.theme=theme;document.querySelector('#light-palette').media=theme==='light'?'all':'not all';const dark=theme==='dark';themeButton.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');themeButton.setAttribute('aria-pressed',String(dark));themeButton.querySelector('.theme-icon').textContent=dark?'☀':'☾';themeButton.querySelector('.theme-label').textContent=dark?'Light mode':'Dark mode';document.querySelector('meta[name="theme-color"]').content=dark?'#080a10':'#fafbff';try{localStorage.setItem('qodvexa-theme',theme)}catch(e){}dispatchEvent(new Event('qodvexa-themechange'))}
themeButton.addEventListener('click',()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));applyTheme(document.documentElement.dataset.theme||'light');
